      AutoCompactorPass(
        pass: pass.pass,
        tokensBefore: pass.tokensBefore,
        tokensAfter: pass.tokensAfter,
        // Name the engine + pass kind: a host watching the report can
        // tell a structured fold from a classic summary (issue #438),
